head.script:
// 메뉴 표시 위치(버튼 영역 오른쪽)
scwin.MENU_X = 360;
scwin.MENU_Y = 150;

// 화면에 표시된 Save·Close 항목 상태
scwin.getScreenState = function () {
    let portal = document.getElementById(cm_menu.id + "_portal");
    let save = portal ? portal.querySelector("li[data-item-id='m_save']") : null;
    let close = portal ? portal.querySelector("li[data-item-id='m_close']") : null;
    let saveText = save ? (save.className.indexOf("w2contextMenu_disabled") > -1 ? "비활성" : "활성") : "없음";
    let closeText = close && close.offsetParent !== null ? "표시" : "숨김";
    return "Save : " + saveText + " / Close : " + closeText;
};

scwin.cm_menu_onopen = function (info) {
    scwin.setReturnValue("메뉴 열림 → " + scwin.getScreenState());
};

scwin.cm_menu_onitemclick = function (info) {
    scwin.setReturnValue("항목 클릭 : " + info.label);
};

// 닫힌 상태에서 설정
scwin.btn_setClosed_onclick = function (e) {
    cm_menu.close();
    cm_menu.setDisabledItem("m_save", true);
    cm_menu.setVisibleItem("m_close", false);
    scwin.setReturnValue("닫힌 상태에서 설정 : Save 비활성, Close 숨김");
};

// 메뉴 열기
scwin.btn_open_onclick = function (e) {
    cm_menu.open(scwin.MENU_X, scwin.MENU_Y);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
